/* Generated by tools/build-docs-bundle.mjs. Edit assets/content/docs/ instead. */
(function () {
  'use strict';
  var bodies = {
  "overview/introduction": "\u003cp>CoreToolsX is a Paper-only vanilla+ tool progression plugin for Minecraft/Paper 1.21.11 or newer and Java 21 or newer. It uses normal crafting and vanilla item behavior instead of custom menus, economies or databases.\u003c/p>\n\u003ch2 id=\"runtime-model\">Two item models\u003c/h2>\u003cp>Normal upgraded tools use their Bukkit material as the source of truth and receive no CoreToolsX persistent data. Skinned netherite tools store their clean material, visual skin, original lore state, inventory model mode and optional cosmetic durability in Paper persistent data.\u003c/p>\n\u003ch2 id=\"supported-tools\">Supported tools\u003c/h2>\u003cp>Swords, pickaxes, axes, shovels, hoes and spears participate in the default upgrade, skin and cost model.\u003c/p>\n\u003ch2 id=\"standalone-scope\">Standalone scope\u003c/h2>\u003cp>CoreToolsX does not require Vault, PlaceholderAPI, a database, a GUI library, CoreArmorX or a custom-item plugin. The resource pack is optional and used only for \u003ccode>REAL_TIER\u003c/code> inventory models.\u003c/p>\n\u003ch2 id=\"defaults\">Conservative defaults\u003c/h2>\u003cul>\u003cli>Progression locks are disabled.\u003c/li>\u003cli>Skin durability is disabled.\u003c/li>\u003cli>Fire/lava skin stripping is disabled.\u003c/li>\u003cli>Foreign persistent data blocks transformations.\u003c/li>\u003cli>\u003ccode>VISUAL_SKIN\u003c/code> requires no resource pack.\u003c/li>\u003c/ul>\n",
  "overview/progression-and-recipes": "\u003cp>CoreToolsX routes protected direct tool crafting through configurable upgrade definitions. The bundled path is wood → stone → copper → iron → diamond, with iron → gold as an alternate endpoint.\u003c/p>\n\u003ch2 id=\"default-routes\">Default routes\u003c/h2>\u003cul>\u003cli>\u003ccode>WOOD → STONE\u003c/code>\u003c/li>\u003cli>\u003ccode>STONE → COPPER\u003c/code>\u003c/li>\u003cli>\u003ccode>COPPER → IRON\u003c/code>\u003c/li>\u003cli>\u003ccode>IRON → DIAMOND\u003c/code>\u003c/li>\u003cli>\u003ccode>IRON → GOLD\u003c/code>\u003c/li>\u003c/ul>\n\u003ch2 id=\"supported-tools\">Supported tools and costs\u003c/h2>\u003cp>Swords, pickaxes, axes, shovels, hoes and spears are supported. \u003ccode>VANILLA_RECIPE_COST\u003c/code> uses 1 for shovel/spear, 2 for sword/hoe and 3 for pickaxe/axe. \u003ccode>CUSTOM\u003c/code> reads a positive \u003ccode>count\u003c/code>.\u003c/p>\n\u003ch2 id=\"recipe-model\">Recipe model\u003c/h2>\u003cp>Ingredient groups accept configured Bukkit materials. Runtime matching requires separate one-item ingredient slots. Static recipe-book entries aid discovery while runtime validation checks the real item, metadata, cost and permission.\u003c/p>\n\u003ch2 id=\"protected-vanilla-recipes\">Protected vanilla recipes\u003c/h2>\u003cp>With override enabled, protected direct outputs use matching \u003ccode>minecraft:*\u003c/code> keys. Wooden tool crafting and vanilla diamond-to-netherite smithing remain untouched. Original recipes return when override is disabled or the plugin stops.\u003c/p>\n\u003ch2 id=\"durability\">Upgrade durability\u003c/h2>\u003cp>Outputs can \u003ccode>REFILL\u003c/code>, \u003ccode>KEEP_DAMAGE\u003c/code> or \u003ccode>KEEP_PERCENTAGE\u003c/code>; repair cost preservation is separately configurable.\u003c/p>\n",
  "overview/netherite-skins": "\u003cp>Skin recipes accept clean netherite tools and convert them to a vanilla visual material while applying netherite-equivalent tool/weapon components. Already-skinned items must be stripped first.\u003c/p>\n\u003ch2 id=\"default-skins\">Default skins\u003c/h2>\u003cp>Wood, stone, copper, iron, gold and diamond skins cover sword, pickaxe, axe, shovel, hoe and spear.\u003c/p>\n\u003ch2 id=\"inventory-models\">Inventory model modes\u003c/h2>\u003cp>\u003ccode>VISUAL_SKIN\u003c/code> is the default: inventory and hand show the visual material and no resource pack is required. \u003ccode>REAL_TIER\u003c/code> assigns \u003ccode>item_model: coretoolsx:skinned/&lt;material_tool&gt;\u003c/code> and requires the separate addon so GUI/ground/fixed/shelf contexts show netherite while the hand retains the visual skin.\u003c/p>\n\u003ch2 id=\"lore\">Lore\u003c/h2>\u003cp>\u003ccode>skins.lore.generated-lines\u003c/code> controls final lore. A standalone \u003ccode>{item_lore}\u003c/code> entry reinserts the saved original lore. Other placeholders cover skin identity, clean/visual/real tier and cosmetic durability.\u003c/p>\n\u003ch2 id=\"skin-durability\">Cosmetic durability\u003c/h2>\u003cp>Modes are \u003ccode>DISABLED\u003c/code>, \u003ccode>GLOBAL\u003c/code>, \u003ccode>BY_SKIN\u003c/code> and \u003ccode>BY_ITEM\u003c/code>. Damage currently mirrors real item damage. Break action is \u003ccode>REMOVE_SKIN\u003c/code>; mending can be \u003ccode>DISABLED\u003c/code>, \u003ccode>SPLIT\u003c/code> or \u003ccode>DOUBLE\u003c/code>.\u003c/p>\n\u003ch2 id=\"removal-and-fire\">Removal and fire\u003c/h2>\u003cp>By default, a skinned tool plus shears returns clean netherite and damages the shears by one. Dropped skinned tools are protected from configured fire/lava destruction while stripping is disabled; when enabled, those causes strip the skin.\u003c/p>\n",
  "overview/item-safety": "\u003cp>CoreToolsX preserves supported data while changing tool materials: custom name, original lore, enchantments, durability damage, max damage where supported, repair cost, flags, compatible custom data and non-CoreToolsX persistent data.\u003c/p>\n\u003ch2 id=\"foreign-data\">Foreign custom data\u003c/h2>\u003cp>\u003ccode>BLOCK_IF_DETECTED\u003c/code> is the safe default. \u003ccode>REPLACE_ANYWAY\u003c/code> permits transformations with foreign PDC and should be used only after compatibility is understood.\u003c/p>\n\u003ch2 id=\"identity\">CoreToolsX identity\u003c/h2>\u003cp>Only skinned tools and internal skin state carry CoreToolsX identity. Normal upgraded tools remain ordinary vanilla items.\u003c/p>\n\u003ch2 id=\"admin-repair\">Inspection and repair\u003c/h2>\u003cp>\u003ccode>/coretoolsx inspect\u003c/code> reports the held item’s current and clean materials, skin, model mode, lore snapshot and durability. \u003ccode>/coretoolsx fixitem\u003c/code> reapplies the configured profile/display to a recognized skinned tool; it is not a generic item converter.\u003c/p>\n",
  "getting-started/installation": "\u003ch2 id=\"requirements\">Requirements\u003c/h2>\u003cul>\u003cli>Paper/Minecraft 1.21.11 or newer.\u003c/li>\u003cli>Java 21 or newer.\u003c/li>\u003cli>The CoreToolsX JAR from \u003ca href=\"https://modrinth.com/plugin/coretoolsx\" target=\"_blank\" rel=\"noopener noreferrer\">Modrinth\u003c/a>.\u003c/li>\u003c/ul>\n\u003ch2 id=\"download\">Download\u003c/h2>\u003cp>Use the public Modrinth project for stable builds. The private plugin source repository is not a download or documentation endpoint.\u003c/p>\n\u003ch2 id=\"install\">Installation flow\u003c/h2>\u003col>\u003cli>Stop Paper.\u003c/li>\u003cli>Place \u003ccode>CoreToolsX-2026.1.2.jar\u003c/code> in \u003ccode>plugins/\u003c/code>.\u003c/li>\u003cli>Start once and review configuration warnings.\u003c/li>\u003cli>Edit \u003ccode>plugins/CoreToolsX/*.yml\u003c/code>.\u003c/li>\u003cli>Run \u003ccode>/coretoolsx reload\u003c/code>.\u003c/li>\u003c/ol>\n\u003ch2 id=\"generated-files\">Generated files\u003c/h2>\u003cpre>\u003ccode>plugins/CoreToolsX/\n├── config.yml\n├── tool-upgrades.yml\n├── tool-skins.yml\n└── messages.yml\u003c/code>\u003c/pre>\n\u003cp>The resource pack is a separate client addon; it is not generated in this folder. \u003ccode>plugin.yml\u003c/code> is internal JAR metadata, not server configuration.\u003c/p>\n",
  "getting-started/reload-vs-restart": "\u003ch2 id=\"safe-to-reload\">Safe with /coretoolsx reload\u003c/h2>\u003cp>The command reloads all four YAML files, rebuilds validated definitions, removes/re-registers recipes, and normalizes skin fire-resistance policy on online players’ items.\u003c/p>\n\u003cul>\u003cli>Runtime toggles and recipe-book behavior.\u003c/li>\u003cli>Upgrade/skin definitions and messages.\u003c/li>\u003cli>Permission strings stored in YAML and lore templates.\u003c/li>\u003cli>Inventory model and cosmetic durability for newly created or subsequently refreshed skinned items.\u003c/li>\u003c/ul>\n\u003ch2 id=\"restart-required\">Restart required\u003c/h2>\u003cul>\u003cli>Replacing the JAR.\u003c/li>\u003cli>Changing Paper/Minecraft runtime.\u003c/li>\u003cli>Recovering from startup/classloading errors.\u003c/li>\u003cli>Clean-boot validation after broad edits.\u003c/li>\u003c/ul>\n\u003ch2 id=\"resource-pack\">Resource pack changes\u003c/h2>\u003cp>Changing the optional pack ZIP does not require a server restart. Players must reload or reselect the pack client-side.\u003c/p>\n\u003ch2 id=\"existing-files\">Existing files are not merged\u003c/h2>\u003cp>Reload does not add new packaged keys to existing YAML. Compare installed files with synchronized defaults after upgrades.\u003c/p>\n",
  "getting-started/resource-pack-addon": "\u003cp>The CoreToolsX resource-pack addon is required only when \u003ccode>tool-skin.inventory-model.mode: REAL_TIER\u003c/code>. The default \u003ccode>VISUAL_SKIN\u003c/code> mode needs no pack.\u003c/p>\n\u003ch2 id=\"behavior\">What the pack changes\u003c/h2>\u003cp>CoreToolsX stores the skinned tool as its visual vanilla material and assigns \u003ccode>item_model: coretoolsx:skinned/&lt;material_tool&gt;\u003c/code>. The addon shows netherite in GUI, ground, fixed and shelf contexts while keeping the visual skin in hand. Without the pack, a REAL_TIER item has a missing/invalid custom model.\u003c/p>\n\u003ch2 id=\"distribution\">Separate distribution\u003c/h2>\u003cp>The addon comes from the plugin repository’s top-level \u003ccode>resource-pack/\u003c/code> source and must be packaged/distributed separately. It is not a runtime YAML file and is excluded from private configuration synchronization.\u003c/p>\n\u003ch2 id=\"format\">Pack format\u003c/h2>\u003cp>Current metadata starts at resource format \u003ccode>84.0\u003c/code> and accepts later \u003ccode>84.x\u003c/code> minor formats. Review the pack before widening support to a later major format.\u003c/p>\n\u003ch2 id=\"client-refresh\">Client refresh\u003c/h2>\u003cp>After replacing the pack, players must reload or reselect it. No server restart is required for the ZIP itself.\u003c/p>\n",
  "getting-started/first-validation": "\u003ch2 id=\"clean-setup\">Clean setup\u003c/h2>\u003col>\u003cli>Confirm version 2026.1.2 enables on Paper 1.21.11+ with Java 21+.\u003c/li>\u003cli>Run \u003ccode>/coretoolsx reload\u003c/code> and review warnings.\u003c/li>\u003cli>Craft each enabled route with one-item ingredient slots.\u003c/li>\u003cli>Apply, inspect, fix and remove one skin.\u003c/li>\u003cli>Test sword, pickaxe, axe, shovel, hoe and spear behavior.\u003c/li>\u003c/ol>\n\u003ch2 id=\"permissions\">Permission validation\u003c/h2>\u003cp>If locks are enabled, test upgrade, skin, usage and bypass behavior with a non-operator account.\u003c/p>\n\u003ch2 id=\"models\">Model validation\u003c/h2>\u003cp>For \u003ccode>VISUAL_SKIN\u003c/code>, confirm vanilla visual models without a pack. For \u003ccode>REAL_TIER\u003c/code>, install the addon and test hand, inventory, ground and display contexts.\u003c/p>\n\u003ch2 id=\"production-validation-checklist\">Production checklist\u003c/h2>\u003cul>\u003cli>Keep a copy of active YAML.\u003c/li>\u003cli>Confirm intended protected recipes are replaced.\u003c/li>\u003cli>Test foreign custom-item blocking.\u003c/li>\u003cli>Test fire/lava behavior if changed.\u003c/li>\u003cli>Do not assume reload refreshes every existing item immediately.\u003c/li>\u003c/ul>\n",
  "paper/files": "\u003cp>CoreToolsX generates four administrator-facing files in \u003ccode>plugins/CoreToolsX/\u003c/code>.\u003c/p>\n\u003ch2 id=\"file-layout\">Runtime folder\u003c/h2>\u003cp>The folder contains only the four YAML defaults below. The optional resource pack is distributed separately.\u003c/p>\n\u003ch2 id=\"config-yml\">config.yml\u003c/h2>\u003cp>Global model, recipe, ingredient, upgrade, lore, removal, stripping, locks and custom-item safety settings.\u003c/p>\n\u003ch2 id=\"tool-upgrades-yml\">tool-upgrades.yml\u003c/h2>\u003cp>Named progression routes with source/target tiers or materials, ingredients, costs and permissions.\u003c/p>\n\u003ch2 id=\"tool-skins-yml\">tool-skins.yml\u003c/h2>\u003cp>Named netherite skins and optional cosmetic durability.\u003c/p>\n\u003ch2 id=\"messages-yml\">messages.yml\u003c/h2>\u003cp>MiniMessage text for commands, crafting, progression and inspection.\u003c/p>\n\u003ch2 id=\"excluded-files\">Not public configuration\u003c/h2>\u003cp>The resource pack is a separate addon. \u003ccode>plugin.yml\u003c/code> stays inside the JAR. Neither is synchronized as public configuration.\u003c/p>\n",
  "paper/config-yml": "\u003cp>This file controls global behavior. Exact comments/defaults are mounted below from the allow-listed resource.\u003c/p>\n\u003ch2 id=\"key-map\">Key map\u003c/h2>\u003cul>\n\u003cli>\u003ccode>settings.debug\u003c/code>; \u003ccode>tool-skin.inventory-model.mode\u003c/code>\u003c/li>\n\u003cli>\u003ccode>recipes.override-vanilla-equipment-recipes\u003c/code>, \u003ccode>blocked-message-cooldown-ticks\u003c/code>, \u003ccode>recipe-book.enabled\u003c/code>\u003c/li>\n\u003cli>\u003ccode>ingredient-groups.{WOOD_TOOL_MATERIALS,STONE_TOOL_MATERIALS,COPPER_TOOL_MATERIALS,IRON_TOOL_MATERIALS,GOLD_TOOL_MATERIALS,DIAMOND_TOOL_MATERIALS}\u003c/code>\u003c/li>\n\u003cli>\u003ccode>upgrades.{enabled,cost-mode,durability-mode,preserve-repair-cost}\u003c/code>\u003c/li>\n\u003cli>\u003ccode>skins.enabled\u003c/code>, \u003ccode>skins.lore.{enabled,format,generated-lines}\u003c/code>\u003c/li>\n\u003cli>\u003ccode>skin-removal.{enabled,tool,consume-tool,damage-tool,damage-amount}\u003c/code>\u003c/li>\n\u003cli>\u003ccode>skin-stripping.{enabled,causes,mode}\u003c/code>\u003c/li>\n\u003cli>\u003ccode>progression-locks.enabled\u003c/code>, \u003ccode>blocks.{crafting,upgrades,usage}\u003c/code>, \u003ccode>permissions.{bypass,usage-prefix}\u003c/code>\u003c/li>\n\u003cli>\u003ccode>compatibility.custom-items.behavior\u003c/code>\u003c/li>\u003c/ul>\n\u003ch2 id=\"supported-values\">Supported values\u003c/h2>\u003cp>Models: \u003ccode>VISUAL_SKIN|REAL_TIER\u003c/code>. Costs: \u003ccode>VANILLA_RECIPE_COST|CUSTOM\u003c/code>. Durability: \u003ccode>REFILL|KEEP_DAMAGE|KEEP_PERCENTAGE\u003c/code>. Stripping mode currently only \u003ccode>STRIP_SKIN\u003c/code>. Custom items: \u003ccode>BLOCK_IF_DETECTED|REPLACE_ANYWAY\u003c/code>.\u003c/p>\n\u003cdiv class=\"config-file-mount\" data-config-file=\"paper/config.yml\">\u003c/div>\n",
  "paper/tool-upgrades-yml": "\u003cp>Each child of \u003ccode>upgrades\u003c/code> is an independent route.\u003c/p>\n\u003ch2 id=\"definition-schema\">Definition schema\u003c/h2>\u003cul>\u003cli>\u003ccode>enabled\u003c/code>.\u003c/li>\u003cli>\u003ccode>from-tier\u003c/code> or exact \u003ccode>from-material\u003c/code>.\u003c/li>\u003cli>\u003ccode>to-tier\u003c/code> or exact \u003ccode>to-material\u003c/code>.\u003c/li>\u003cli>\u003ccode>ingredient\u003c/code>: Bukkit material or configured group.\u003c/li>\u003cli>\u003ccode>cost-mode\u003c/code>: \u003ccode>VANILLA_RECIPE_COST|CUSTOM\u003c/code>.\u003c/li>\u003cli>Positive \u003ccode>count\u003c/code> for a custom cost.\u003c/li>\u003cli>\u003ccode>permission\u003c/code> when locks apply.\u003c/li>\u003c/ul>\n\u003ch2 id=\"defaults\">Bundled definitions\u003c/h2>\u003cp>\u003ccode>wood_to_stone\u003c/code>, \u003ccode>stone_to_copper\u003c/code>, \u003ccode>copper_to_iron\u003c/code>, \u003ccode>iron_to_gold\u003c/code> and \u003ccode>iron_to_diamond\u003c/code>. Supported tiers are wood, stone, copper, iron, gold, diamond and netherite.\u003c/p>\n\u003ch2 id=\"validation\">Validation\u003c/h2>\u003cp>Missing endpoints, unknown materials/groups and invalid costs disable the affected definition with a warning.\u003c/p>\n\u003cdiv class=\"config-file-mount\" data-config-file=\"paper/tool-upgrades.yml\">\u003c/div>\n",
  "paper/tool-skins-yml": "\u003cp>This file defines netherite visual skins and optional cosmetic durability.\u003c/p>\n\u003ch2 id=\"skin-schema\">Skin definition schema\u003c/h2>\u003cp>\u003ccode>skins.&lt;id&gt;\u003c/code> supports \u003ccode>enabled\u003c/code>, \u003ccode>display-name\u003c/code>, \u003ccode>ingredient\u003c/code>, \u003ccode>cost-mode\u003c/code>, positive custom \u003ccode>count\u003c/code> and \u003ccode>permission\u003c/code>. Defaults are wood, stone, copper, iron, gold and diamond.\u003c/p>\n\u003ch2 id=\"durability-schema\">Cosmetic durability schema\u003c/h2>\u003cul>\u003cli>\u003ccode>skin-durability.mode\u003c/code>: \u003ccode>DISABLED|GLOBAL|BY_SKIN|BY_ITEM\u003c/code>.\u003c/li>\u003cli>\u003ccode>global.max-durability\u003c/code>.\u003c/li>\u003cli>\u003ccode>by-skin.{default-max-durability,materials.&lt;skin&gt;}\u003c/code>.\u003c/li>\u003cli>\u003ccode>by-item.default-max-durability\u003c/code> and \u003ccode>by-item.materials.&lt;skin&gt;.{default-max-durability,sword,pickaxe,axe,shovel,hoe,spear}\u003c/code>.\u003c/li>\u003cli>\u003ccode>damage.{mode,multiplier}\u003c/code>; mode currently only \u003ccode>MIRROR_REAL_DAMAGE\u003c/code>.\u003c/li>\u003cli>\u003ccode>on-break\u003c/code>, currently only \u003ccode>REMOVE_SKIN\u003c/code>.\u003c/li>\u003cli>\u003ccode>mending.mode\u003c/code>: \u003ccode>DISABLED|SPLIT|DOUBLE\u003c/code>.\u003c/li>\u003cli>\u003ccode>placeholders.{disabled-value,bar-segments,bar-full,bar-empty}\u003c/code>.\u003c/li>\u003c/ul>\n\u003cdiv class=\"config-file-mount\" data-config-file=\"paper/tool-skins.yml\">\u003c/div>\n",
  "paper/messages-yml": "\u003cp>Messages use Adventure MiniMessage. The prefix is prepended automatically. Placeholders are available only where the event supplies them.\u003c/p>\n\u003ch2 id=\"key-map\">Message key map\u003c/h2>\u003cul>\u003cli>\u003ccode>prefix\u003c/code>\u003c/li>\u003cli>\u003ccode>commands.{no-permission,unknown,reloaded,version,help-header,help-version,help-reload,help-inspect,help-fixitem,player-only}\u003c/code>\u003c/li>\u003cli>\u003ccode>crafting.{blocked-vanilla-craft,no-permission,custom-item-blocked}\u003c/code>\u003c/li>\u003cli>\u003ccode>progression.usage-blocked\u003c/code>\u003c/li>\u003cli>\u003ccode>admin.{inspect-empty-hand,fix-empty-hand,fix-not-skinned,fixed}\u003c/code>\u003c/li>\u003cli>\u003ccode>admin.inspect.{header,current-material,clean-material,visual-skin,inventory-model-mode,has-core-data,generated-lore,original-lore,skin-durability,skin-durability-disabled,tier,piece}\u003c/code>\u003c/li>\u003c/ul>\n\u003ch2 id=\"placeholders\">Placeholders\u003c/h2>\u003cp>Examples include \u003ccode>{version}\u003c/code>, \u003ccode>{material}\u003c/code>, \u003ccode>{skin}\u003c/code>, \u003ccode>{mode}\u003c/code>, \u003ccode>{damage}\u003c/code>, \u003ccode>{remaining}\u003c/code>, \u003ccode>{max}\u003c/code>, \u003ccode>{percent}\u003c/code>, \u003ccode>{tier}\u003c/code> and \u003ccode>{piece}\u003c/code>.\u003c/p>\n\u003cdiv class=\"config-file-mount\" data-config-file=\"paper/messages.yml\">\u003c/div>\n",
  "reference/command-reference": "\u003ctable>\u003cthead>\u003ctr>\u003cth>Command\u003c/th>\u003cth>Behavior\u003c/th>\u003cth>Permission\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\n\u003ctr>\u003ctd>\u003ccode>/coretoolsx help\u003c/code>\u003c/td>\u003ctd>Shows commands available to the sender.\u003c/td>\u003ctd>None\u003c/td>\u003c/tr>\n\u003ctr>\u003ctd>\u003ccode>/coretoolsx version\u003c/code>\u003c/td>\u003ctd>Shows the installed version.\u003c/td>\u003ctd>None\u003c/td>\u003c/tr>\n\u003ctr>\u003ctd>\u003ccode>/coretoolsx reload\u003c/code>\u003c/td>\u003ctd>Reloads configuration, definitions, messages and recipes.\u003c/td>\u003ctd>\u003ccode>coretoolsx.admin.reload\u003c/code>\u003c/td>\u003c/tr>\n\u003ctr>\u003ctd>\u003ccode>/coretoolsx inspect\u003c/code>\u003c/td>\u003ctd>Inspects the held tool; player-only.\u003c/td>\u003ctd>\u003ccode>coretoolsx.admin.inspect\u003c/code>\u003c/td>\u003c/tr>\n\u003ctr>\u003ctd>\u003ccode>/coretoolsx fixitem\u003c/code>\u003c/td>\u003ctd>Refreshes a recognized held skinned tool; player-only.\u003c/td>\u003ctd>\u003ccode>coretoolsx.admin.fixitem\u003c/code>\u003c/td>\u003c/tr>\n\u003c/tbody>\u003c/table>\u003cp>Alias: \u003ccode>/ctx\u003c/code>. Admin tab completions require their matching permissions.\u003c/p>\n",
  "reference/permission-reference": "\u003ch2 id=\"admin\">Administration\u003c/h2>\u003cul>\u003cli>\u003ccode>coretoolsx.admin\u003c/code> — operator-default aggregate for reload, inspect, fixitem and bypass.\u003c/li>\u003cli>\u003ccode>coretoolsx.admin.reload\u003c/code>, \u003ccode>.inspect\u003c/code>, \u003ccode>.fixitem\u003c/code>.\u003c/li>\u003cli>\u003ccode>coretoolsx.progression.bypass\u003c/code>.\u003c/li>\u003c/ul>\n\u003ch2 id=\"skins\">Skins\u003c/h2>\u003cp>\u003ccode>coretoolsx.skin.*\u003c/code> aggregates wood, stone, copper, iron, gold and diamond skin nodes.\u003c/p>\n\u003ch2 id=\"upgrades\">Upgrades\u003c/h2>\u003cp>\u003ccode>coretoolsx.upgrade.*\u003c/code> aggregates wood_to_stone, stone_to_copper, copper_to_iron, iron_to_gold and iron_to_diamond nodes.\u003c/p>\n\u003ch2 id=\"usage\">Usage locks\u003c/h2>\u003cp>\u003ccode>coretoolsx.use.*\u003c/code> aggregates wood, stone, copper, iron, gold, diamond and netherite nodes. Usage checks run only when locks and \u003ccode>blocks.usage\u003c/code> are enabled. Definition permissions and usage prefix can be changed in YAML.\u003c/p>\n",
  "reference/troubleshooting-quick-reference": "\u003ch2 id=\"startup\">Plugin does not enable\u003c/h2>\u003cp>Confirm Paper/Minecraft 1.21.11+, Java 21+, the correct JAR and complete startup logs.\u003c/p>\n\u003ch2 id=\"recipe-output\">A recipe appears but will not craft\u003c/h2>\u003cp>Use separate one-item ingredient slots. Check definition enablement, groups, permissions, already-skinned bases and custom-item protection.\u003c/p>\n\u003ch2 id=\"vanilla-recipe\">A direct vanilla recipe still works\u003c/h2>\u003cp>Check the override, reload and warnings. Wooden crafting and diamond-to-netherite smithing are intentionally untouched.\u003c/p>\n\u003ch2 id=\"missing-model\">A REAL_TIER item has a missing model\u003c/h2>\u003cp>Install/enable the matching CoreToolsX addon. Use \u003ccode>VISUAL_SKIN\u003c/code> if no resource pack should be required.\u003c/p>\n\u003ch2 id=\"reload\">Reload does not change an existing item\u003c/h2>\u003cp>Reload affects new/refreshed items. Use \u003ccode>/coretoolsx fixitem\u003c/code> on a recognized skinned item when appropriate.\u003c/p>\n\u003ch2 id=\"custom-item\">A custom item is blocked\u003c/h2>\u003cp>The safe default rejects foreign PDC. Do not use \u003ccode>REPLACE_ANYWAY\u003c/code> until compatibility is understood.\u003c/p>\n",
  "reference/faq": "\u003ch2 id=\"requirements\">What does CoreToolsX require?\u003c/h2>\u003cp>Paper/Minecraft 1.21.11+ and Java 21+.\u003c/p>\n\u003ch2 id=\"dependencies\">Does it require Vault, PlaceholderAPI, a database or CoreArmorX?\u003c/h2>\u003cp>No. It also needs no GUI library or custom-item plugin.\u003c/p>\n\u003ch2 id=\"resource-pack\">Is a resource pack mandatory?\u003c/h2>\u003cp>No. It is required only for \u003ccode>REAL_TIER\u003c/code>; default \u003ccode>VISUAL_SKIN\u003c/code> is pack-free.\u003c/p>\n\u003ch2 id=\"normal-items\">Do normal upgrades receive plugin data?\u003c/h2>\u003cp>No. Normal upgraded tools remain material-driven vanilla items.\u003c/p>\n\u003ch2 id=\"supported-tools\">Which types are supported?\u003c/h2>\u003cp>Sword, pickaxe, axe, shovel, hoe and spear.\u003c/p>\n\u003ch2 id=\"unlock-data\">Where is progression stored?\u003c/h2>\u003cp>CoreToolsX stores none; locks are permission-based.\u003c/p>\n\u003ch2 id=\"reload\">What follows a normal YAML edit?\u003c/h2>\u003cp>Run \u003ccode>/coretoolsx reload\u003c/code> and review warnings.\u003c/p>\n",
  "reference/support-policy": "\u003ch2 id=\"release-channels\">Release channels\u003c/h2>\u003cp>CoreToolsX is free to download and use. Public stable releases are distributed through Modrinth. Paid memberships do not sell the stable plugin.\u003c/p>\n\u003ch2 id=\"supporter-preview-builds\">Supporter preview builds\u003c/h2>\u003cp>Supporters may receive temporary previews, release candidates, staging builds and non-critical hotfix candidates for testing. They are not supporter-exclusive stable releases.\u003c/p>\n\u003ch2 id=\"critical-fix-policy\">Critical fixes\u003c/h2>\u003cp>Confirmed security, exploit, data-loss, major-crash and other critical stability fixes are released publicly when ready.\u003c/p>\n\u003ch2 id=\"paid-memberships\">Paid memberships\u003c/h2>\u003cp>Membership may include priority support, setup/configuration review, troubleshooting, debug/log analysis, preview channels, roadmap updates and testing participation. It does not unlock in-game functionality.\u003c/p>\n\u003ch2 id=\"discord-authentication\">Discord authentication\u003c/h2>\u003cp>The bot verifies active Patreon membership and assigns Discord roles. The plugin does not require Patreon authentication.\u003c/p>\n\u003ch2 id=\"disclaimer\">Disclaimer\u003c/h2>\u003cp>CoreToolsX is an independent server-side plugin. NOT AN OFFICIAL MINECRAFT PRODUCT. NOT APPROVED BY OR ASSOCIATED WITH MOJANG OR MICROSOFT.\u003c/p>\n",
  "reference/source-notes": "\u003cp>This documentation targets CoreToolsX 2026.1.2 at plugin revision \u003ccode>f8727442637877695643e11810df07ce06d47d4b\u003c/code>. Claims were checked against current source, bundled defaults, public feature/configuration documents and public project identities.\u003c/p>\n\u003ch2 id=\"configuration-source\">Configuration source\u003c/h2>\u003cp>The website synchronizes only \u003ccode>config.yml\u003c/code>, \u003ccode>tool-upgrades.yml\u003c/code>, \u003ccode>tool-skins.yml\u003c/code> and \u003ccode>messages.yml\u003c/code>. The browser bundle contains public defaults only.\u003c/p>\n\u003ch2 id=\"excluded\">Excluded material\u003c/h2>\u003cp>\u003ccode>plugin.yml\u003c/code>, Java sources, tests, metadata, credentials, runtime/player data and the separate resource-pack tree are excluded from configuration sync.\u003c/p>\n\u003ch2 id=\"evidence-limits\">Evidence limits\u003c/h2>\u003cp>Documentation review does not prove a fresh build, live server run, third-party compatibility or production deployment. Paper is the formal runtime contract.\u003c/p>\n"
};
  var docs = window.COREX_DOCS;
  if (!docs || !Array.isArray(docs.articles)) throw new Error('Load docs-content.js before docs-bodies.js.');
  // Restore the bodyHtml contract consumed by the wiki, search and full reference.
  docs.articles.forEach(function (article) {
    if (!Object.prototype.hasOwnProperty.call(bodies, article.id)) throw new Error('Documentation bundle missing article: ' + article.id);
    article.bodyHtml = bodies[article.id];
  });
}());
